      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染，浅表淋巴结未触及肿大。头颅无畸形，五官端正。双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓无畸形。双肺呼吸音清，未闻及干湿性啰音。心界不大，心率{hr}次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹部查体。双下肢无水肿，病理征阴性。",
