        "variationAnalysis": "1.住院时间延长：\n   - 原因：血糖波动大需多次调整方案；合并糖尿病酮症酸中毒（DKA）或高渗高血糖综合征（HHS）需延长治疗；严重并发症（糖尿病肾病IV期、增殖期视网膜病变、糖尿病足）需多科会诊\n   - 依据《中国2型糖尿病防治指南（2020版）》：DKA需积极补液+小剂量胰岛素静脉滴注，纠正电解质紊乱，住院时间延长\n2.治疗方案变更：\n   - 原因：口服药联合治疗效果不佳需起始胰岛素治疗；发现严重并发症需调整治疗方案（如肾病需停用二甲双胍）；药物不良反应（肝功能异常、低血糖）需更换药物\n   - 依据《中国2型糖尿病防治指南（2020版）》：eGFR<45ml/min/1.73m2应减量或停用二甲双胍；HbA1c>=9.0%伴症状应起始胰岛素\n3.转诊指征：\n   - 糖尿病足溃疡需血管外科或创面处理；增殖期视网膜病变需眼科激光或手术；终末期糖尿病肾病需透析或肾移植评估；反复低血糖或血糖极度不稳定需内分泌专科调整\n   - 依据《中国2型糖尿病防治指南（2020版）》及《国家基层糖尿病防治管理指南（2022）》",
