      "auxiliaryExam": "{date} {time} 血常规：血红蛋白 {hb}g/L、红细胞 {rbc}×10^12/L、红细胞压积 {hct}%。\n{date} {time2} 肝功能：ALT {alt}U/L、AST {ast}U/L、总胆红素 {tbil}μmol/L、白蛋白 {alb}g/L。\n{date} {time3} 肾功能：尿素氮 {bun}mmol/L、肌酐 {cr}μmol/L。\n{date} 凝血功能：PT {pt}秒、APTT {aptt}秒。\n{date} 急诊胃镜：{site}溃疡（Forrest {forrest}级）/食管胃底静脉曲张破裂出血。",
