      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。头颅无畸形，五官端正。双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓及两肺查体。心界不大，心率{hr}次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛及反跳痛，肝脾肋下未触及，肠鸣音正常。双下肢无水肿，生理反射存在，病理征阴性。",
