      "dailyCourse": "{主治}主治医师查房记录（入院第1天）\n  时间：{date} {time}\n  患者因\"发热、胸痛伴咳嗽{days}天。\"入院第1天。今晨{主治}主治医师查房，患者诉主诉症状较入院前有所改善，但仍有轻度憋喘与乏力，昨日24小时出入量平衡。无畏寒发热，无剧烈疼痛。\n  查体示：T：{t}\tP:{p}\tR:{r}\tBP：{bp}\n  神志清晰，慢性病容，自主体位。心肺听诊未见明显杂音，腹部平软无压痛，双下肢无水肿。专科体查符合该病早期改变。\n  辅助检查：急诊血常规：WBC {wbc}×10^9/L、Hb {hb}g/L；生化全套：肌酐 {cr}μmol/L、钾 {K}mmol/L；专科检查明确。\n  {主治}主治医师查房后意见：\n  分析：审核患者病史、体征及辅助检查，结核性胸膜炎诊断明确。目前患者处于急性期阶段，治疗重点在于快速控制急性症状、保护重要脏器功能，防止并发症发生。\n  指示：①遵医嘱给予胸腔穿刺抽液引流 + HRZE四联抗结核 + 水飞蓟宾护肝；②密切监测生命体征与专科症状，每4小时评估一次；③记录24小时出入量；④安排明日复查生化及电解质。\n\n\t医师签名：\n\n{主任}科主任查房记录（入院第2天）\n  时间：{date}\n  {主任}科主任查房记录：\n  今{主任}科主任查房，患者诉主诉症状进一步减轻，夜间睡眠改善，食欲恢复，二便正常。无畏寒、发热，无胸闷、心悸。\n  查体示：T：{t2}\tP:{p2}\tR:{r2}\tBP：{bp2}\n  一般情况良好，面色较前红润，神志清晰，自主体位。双肺听诊呼吸音清，心律齐，专科体查阳性体征较入院时减轻。\n  辅助检查：复查血常规：WBC {wbc2}×10^9/L；肾功能：肌酐 {cr}μmol/L、尿素氮 {bun}mmol/L；电解质：钾 {K2}mmol/L、钠 {Na2}mmol/L，各指标均改善。\n  {主任}科主任查房后意见：\n  分析：结合患者病情演变及最新检验指标分析：①入院后给予规范处置，主诉症状明显缓解，说明初始治疗方案有效；②复查检验指标改善，脏器功能稳定，无绞窄、重症化及并发症征象；③电解质及内环境稳定。\n  指示：①继续维持当前规范治疗；②根据复查结果精确调整给药剂量；③鼓励患者适当离床活动；④密切观察病情变化。\n\n\t医师签名：\n\n日常病程记录（入院第3天/48-72小时疗效评估）\n  时间：{date}\n  患者诉主要临床症状基本消退，精神及体力显著恢复，无憋喘及疼痛发作。食欲佳，睡眠安，大小便完全恢复正常。\n  查体示：T：{t3}\tP:{p3}\tR:{r3}\tBP：{bp3}\n  一般情况佳，神志清晰，自主体位。双肺未闻及干湿性啰音，心率72次/分，律齐，专科查体恢复正常。\n  辅助检查：复查专科核心指标改善显著，血沉、BNP、血气或电解质指标均趋于正常范围。\n  {主治}主治医师查房后意见：\n  综合评估患者近阶段治疗反应：患者主诉核心症状明显减轻，夜间睡眠及饮食恢复，精神体力好转；查体阳性体征显著消退，生命体征维持平稳；复查关键生化及专科指标改善满意。综合判断病情已取得明确好转转归，疗效肯定。\n  指示：①胸痛消退，体温复常，超声示胸水吸收，维持HRZE四联抗结核；②指导患者康复锻炼与口服维持用药宣教；③准备办理出院。\n\n\t医师签名：\n\n日常病程记录（入院第5天/治疗中期评估）\n  时间：{date}\n  患者诉无任何不适主诉，饮食及大小便正常，体力活动耐量完全恢复正常。\n  查体示：T：{t4}\tP:{p4}\tR:{r4}\tBP：{bp4}\n  一般情况良好，神志清晰，自主体位。心肺听诊清，专科体查无阳性发现。\n  辅助检查：复查血常规WBC {wbc3}×10^9/L、中性粒细胞百分比{neupct3}%，肌酐、血钾均在正常范围。\n  {主治}主治医师查房后意见：\n  中期治疗病情评估：患者目前无特殊不适主诉，日常饮食及离床活动耐量完全恢复；全身体查及专科阳性体征均已消退；复查血常规、电解质及脏器功能指标完全正常。评估病情已获得稳定控制，口服维持方案耐受良好。\n  指示：①继续口服维持方案；②进行出院前健康宣教；③计划2日后办理出院。\n\n\t医师签名：\n\n{主任}科主任查房记录（出院前评估）\n  时间：{date}\n  {主任}科主任查房记录：\n  今{主任}科主任查房评估出院条件。患者诉无任何不适，饮食睡眠良好，二便正常，请求出院。\n  查体示：T：{t5}\tP:{p5}\tR:{r5}\tBP：{bp5}\n  一般情况良好，面色如常，自主体位。心肺及全身体查均无异常。\n  辅助检查：出院前复查全套指标（血常规、凝血、肝肾功能、电解质、专科功能）均完全达标。\n  {主任}科主任查房后意见：\n  出院条件综合评估：\n  审核患者病史、体格检查及出院前各项复查检验指标：患者主诉及伴随症状彻底消除，一般情况良好，体力活动耐量恢复正常；查体专科体征阴性，切口/穿刺点愈合好；复查全套生化、电解质及专科核心指标均恢复至正常范围。综合评估患者病情已完全恢复，符合临床出院标准，同意今日办理出院。\n  患者结核性胸膜炎经治疗后病情完全缓解，各项出院标准均达标，同意出院。\n  出院医嘱：①出院后注意饮食与作息调节，保持良好生活习惯；②按时服用出院带药，切勿擅自停药或减量；③定期门诊随访复查。\n  同意出院。\n\n\t医师签名：",
      "dischargeRecord": "主诉：发热、胸痛伴咳嗽{days}天。\n入院情况：患者为{age}岁{gender}，急性病程，因\"发热、胸痛伴咳嗽{days}天\"入院。专科检查：右侧胸壁呼吸运动度减弱，右下肺触觉语颤减弱，叩诊呈浊音，呼吸音显著减弱，右中肺可闻及胸膜摩擦音。左肺听诊正常。辅助检查：{date} 胸部CT：右侧中大量胸腔积液伴胸膜增厚。ESR {esr}mm/h，PPD强阳性，T-SPOT阳性。胸水分析：草黄色渗出液，ADA {ada}U/L，淋巴细胞85%。\n初步诊断：1、结核性胸膜炎（右侧）\n2、原发性高血压 2级（高危）\n诊治经过：1、入院后完善相关辅助检查：{date} 胸部CT：右侧胸腔积液；{date} 血沉ESR：{esr}mm/h，CRP：{crp}mg/L；{date} 胸水穿刺分析：草黄色渗出液，李凡他阳性，ADA {ada}U/L，未见癌细胞；2、入院后行超声定位下右侧胸腔穿刺抽液术引流胸水600ml，全面启动HRZE四联抗结核方案（异烟肼+利福平+吡嗪酰胺+乙胺丁醇）配合水飞蓟宾护肝，体温迅速复常，右侧胸痛消退，胸水大部吸收，患者主诉症状完全消退，恢复良好。\n出院情况：患者诉无发热、无低热盗汗、无胸痛及气促，咳嗽基本消除，食欲良好，二便正常。查体示：T：{t}\tP:{p}\tR:{r}\tBP：{bp} 一般情况良好，面色如常，自主体位。心肺及全身体格检查未见明显异常。专科检查：右下肺浊音区缩小，呼吸音显著改善好转，无胸膜摩擦音，心率76次/分，双下肢无水肿。\n出院诊断：1、结核性胸膜炎（右侧）\n2、原发性高血压 2级（高危）\n出院医嘱：\n1、保证充足休息与营养，高蛋白高维生素饮食，切勿劳累；\n2、严格遵医嘱坚持全程、规律口服四联抗结核药物，切勿自行减药、漏药或停药；\n3、每月定期门诊复查肝肾功能、血沉及胸部超声，若出现皮肤发黄或恶心需及时复诊。",
