      "physicalExam": "T: {t}℃ P: {p}次/分 R: {r}次/分 BP: {bp}mmHg\\n发育正常，营养中等，神志清楚，精神可，自主体位，查体合作。全身皮肤黏膜无黄染及出血点，浅表淋巴结未触及肿大。头颅无畸形，五官端正。双侧瞳孔等大等圆，对光反射灵敏。颈软，气管居中，甲状腺未触及肿大。胸廓无畸形。双肺呼吸音清，未闻及干湿性啰音。心界不大，心率{hr}次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛及反跳痛，肝脾肋下未触及，肠鸣音正常。骨关节专科查体。",
      "specialistExam": "风湿免疫科专科检查：神志清晰，生命体征平稳。胸廓对称无畸形，双肺听诊呼吸音清，未闻及干湿性啰音及胸膜摩擦音。心界不大，心率80次/分，心律齐，瓣膜听诊区无病理性杂音。腹部平软，无压痛及反跳痛，肝脾肋下未触及。双下肢无凹陷性水肿，生理反射存在，病理反射未引出。",
      "auxiliaryExam": "{date} 血常规：WBC {wbc}×10^9/L, Hb {hb}g/L, Plt {plt}×10^9/L。\n{date} 生化全套：肝肾功能（肌酐 {cr}μmol/L）、电解质（钾 {k}mmol/L, 钠 {na}mmol/L）基本正常。\n{date} 专科影像及功能检查：心电图/胸片/超声等均支持\"强直性脊柱炎\"临床诊断。",
      "admitDiagnosis": "1、强直性脊柱炎\n2、原发性高血压 3级（极高危）",
