      "presentIllness": "患者于发病前无明显诱因下出现\"发作性左肢麻木无力{hours}小时\"，伴全身乏力、食欲不振及夜眠欠佳。随病程演变，上述症状呈进行性加重，劳累及受凉后胸闷、气促或局部不适感更为显著，严重影响日常生活。患者曾于外院或自行口服药物治疗，效果均不理想。近{hours}小时前，病情进一步急剧加重，遂至我院急诊科就诊。急诊完善生命体征评估、血常规、生化全套及专科影像学检查，提示符合\"短暂性脑缺血发作\"改变，急诊拟\"短暂性脑缺血发作\"收住我科。发病以来精神差，食欲下降，睡眠欠佳，大小便正常，近期体重无明显异常改变。",
